INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Ingin Menyapa tapi Takut Salah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Bahasa Spanyol dipakai lebih dari 500 juta orang di 20 negara. Banyak pemula Indonesia tertarik — karena telenovela, sepak bola, atau rencana traveling — tetapi berhenti di niat karena takut salah pengucapan atau memakai sapaan yang tidak sopan. Kabar baiknya: bahasa Spanyol dibaca persis seperti ditulis, jadi lebih mudah dipelajari daripada bahasa Inggris.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Sapaan Menunjukkan Rasa Hormat$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Di budaya Hispanik, menyapa adalah kewajiban sosial. Masuk toko tanpa mengucap 'buenos dias' dianggap tidak sopan. Ada dua register: formal (usted) untuk orang yang dihormati dan informal (tu) untuk teman. Pemula aman memakai bentuk formal dulu sampai diajak santai. Vokal Spanyol hanya lima (a, e, i, o, u) dan selalu dibaca sama — inilah yang membuat pengucapannya konsisten.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat yang Dibutuhkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Aplikasi kamus Spanyol-Indonesia (misalnya WordReference)$$, $$Aplikasi audio seperti Forvo untuk mendengar penutur asli$$, $$Flashcard (Anki) berisi 10 sapaan inti$$, $$Waktu latihan 15 menit sehari$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Kuasai 10 Sapaan dalam 30 Hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Buenos dias (BWE-nos DI-as) — selamat pagi, dipakai sampai siang$$, $$Buenas tardes (BWE-nas TAR-des) — selamat siang/sore$$, $$Buenas noches (BWE-nas NO-ches) — selamat malam, untuk tiba maupun pergi$$, $$Hola (O-la) — halo, santai dan universal$$, $$Como esta usted? (KO-mo es-TA us-TED) — apa kabar? (formal)$$, $$Como estas? (KO-mo es-TAS) — apa kabar? (informal)$$, $$Me llamo ... (me YA-mo) — nama saya ...$$, $$Mucho gusto (MU-cho GUS-to) — senang bertemu denganmu$$, $$Gracias (GRA-syas) — terima kasih; de nada (de NA-da) — sama-sama$$, $$Adios (a-DYOS) — selamat tinggal; hasta luego (AS-ta lu-E-go) — sampai jumpa$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Kesalahan Umum Pemula$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Memakai 'tu' ke orang tua atau atasan — mulai dengan 'usted' sampai diajak akrab$$, $$Mengucapkan huruf h — dalam bahasa Spanyol h tidak dibunyikan (hola dibaca 'ola')$$, $$Membaca 'j' seperti bahasa Inggris — bunyi 'j' Spanyol seperti 'kh' yang kasar$$, $$Lupa tanda tanya terbalik (tanda seru/tanya pembuka) saat menulis$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pemeriksaan Hasil$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Setelah 30 hari, tantang dirimu: perkenalkan diri dalam bahasa Spanyol ke teman atau di komunitas bahasa daring, lalu catat responsnya. Jika 10 sapaan sudah lancar, langkah berikutnya adalah angka 1–20 dan cara memesan makanan di restoran.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Masalah: Tenggorokan Perih Setiap Menelan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Radang tenggorokan membuat menelan terasa seperti menelan pecahan kaca. Makan jadi tersiksa, bicara serak, kadang disertai demam ringan. Banyak orang langsung panik membeli antibiotik, padahal sebagian besar kasus disebabkan virus dan sembuh sendiri dengan perawatan yang tepat di rumah.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Penjelasan: Apa Itu Radang Tenggorokan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Radang tenggorokan (faringitis) adalah peradangan pada dinding belakang tenggorokan. Penyebab tersering adalah infeksi virus (pilek, flu); sebagian kecil oleh bakteri Streptococcus. Gejalanya: nyeri menelan, tenggorokan kering/gatal, suara serak, kadang demam dan pembesaran kelenjar leher. Catatan: artikel ini berisi informasi umum dan bukan pengganti nasihat medis profesional.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Alat dan Bahan di Rumah$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Garam dapur untuk kumur air garam hangat$$, $$Madu dan lemon (untuk usia di atas 1 tahun)$$, $$Air putih yang cukup$$, $$Pelembap udara atau semangkuk air di kamar ber-AC$$, $$Termometer untuk memantau demam$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Langkah: Perawatan Mandiri 5–7 Hari$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Istirahatkan suara: kurangi bicara dan jangan berbisik (berbisik justru menegangkan pita suara)$$, $$Kumur air garam hangat (setengah sendok teh garam per gelas air) 3–4 kali sehari$$, $$Minum banyak cairan hangat: air putih, teh madu-lemon, atau sup$$, $$Hindari asap rokok, gorengan berminyak, dan minuman bersoda selama sakit$$, $$Minum obat pereda nyeri sesuai dosis kemasan bila nyeri mengganggu$$, $$Jaga kelembapan udara ruangan agar tenggorokan tidak kering$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Risiko: Tanda Bahaya Kapan Harus ke Dokter$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Demam di atas 38,5 derajat yang bertahan lebih dari 3 hari$$, $$Bercak putih/nanah di amandel disertai demam tinggi$$, $$Sulit bernapas, menelan ludah pun tidak bisa, atau air liur menetes$$, $$Nyeri tidak membaik setelah 7 hari perawatan mandiri$$, $$Radang kambuh berulang dalam waktu singkat$$, $$Jangan minum antibiotik tanpa resep dokter — antibiotik tidak mempan untuk virus$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Pencegahan agar Tidak Kambuh$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 11, jsonb_build_object('text', $$Cuci tangan secara rutin, jangan berbagi gelas dan alat makan saat ada yang sakit di rumah, cukup tidur, dan hindari paparan asap rokok. Jika tenggorokan sering meradang, konsultasikan ke dokter untuk mencari pemicunya — bisa alergi, asam lambung naik, atau infeksi berulang yang butuh penanganan khusus.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Samudra: Lebih Dalam dari yang Dibayangkan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Rata-rata kedalaman samudra sekitar 3.700 meter, tetapi di beberapa titik lempeng tektonik menukik ke bawah dan menciptakan palung yang jauh lebih dalam. Kedalaman ini disebut zona hadal — diambil dari nama Hades, dunia bawah dalam mitologi Yunani. Tekanan di sana lebih dari 1.000 kali tekanan atmosfer di permukaan.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$1. Palung Mariana — Titik Terdalam Bumi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Palung Mariana di Samudra Pasifik barat mencapai kedalaman sekitar 10.900–11.000 meter di titik Challenger Deep. Jika Gunung Everest dimasukkan ke dalamnya, puncaknya masih tenggelam sekitar 2 kilometer di bawah permukaan. Terbentuk karena Lempeng Pasifik menunjam ke bawah Lempeng Filipina. Pada 1960, Trieste membawa dua orang ke dasarnya; pada 2012 James Cameron turun solo; ekspedisi modern kini memetakannya dengan sonar multibeam.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$2. Palung Tonga — Palung Terdalam Belahan Selatan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Palung Tonga di selatan Samudra Pasifik mencapai sekitar 10.800 meter di titik Horizon Deep, menjadikannya palung terdalam kedua di dunia sekaligus yang terdalam di belahan selatan. Palung ini sangat aktif secara seismik — menjadi sumber gempa dan tsunami besar, termasuk yang memicu letusan Hunga Tonga pada 2022.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$3. Palung Filipina dan Kermadec$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 7, jsonb_build_object('text', $$Palung Filipina di timur Filipina mencapai sekitar 10.500 meter dan berada dekat Indonesia — menjadikannya tetangga geologi kita. Palung Kermadec di timur laut Selandia Baru mencapai sekitar 10.000 meter dan menjadi jalur migrasi paus bungkuk. Keduanya terbentuk di zona subduksi tempat satu lempeng menelusup ke bawah lempeng lain.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Kehidupan di Kedalaman Ekstrem$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Meski gelap total dan bertekanan raksasa, zona hadal tidak mati. Ditemukan ikan snailfish yang hidup di kedalaman 8.000 meter, amfipoda raksasa, dan mikroba yang memakan bangkai paus yang tenggelam. Ironisnya, mikroplastik pun sudah ditemukan di sedimen palung terdalam — bukti bahwa dampak manusia mencapai tempat yang belum pernah dijamah manusia.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Apa Itu Komputer Kuantum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Komputer biasa bekerja dengan bit: 0 atau 1. Komputer kuantum bekerja dengan qubit yang memanfaatkan hukum fisika kuantum. Untuk masalah tertentu — seperti simulasi molekul obat atau optimasi raksasa — komputer kuantum berpotensi jutaan kali lebih cepat daripada superkomputer tercepat saat ini. Namun ia bukan pengganti laptop; ia adalah mesin khusus untuk masalah khusus.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Bit vs Qubit: Superposisi$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Qubit bisa berada dalam superposisi: 0 dan 1 sekaligus, sampai ia diukur. Analoginya seperti koin yang berputar di udara — bukan kepala atau ekor, melainkan keduanya. Dengan n qubit, komputer kuantum bisa merepresentasikan 2 pangkat n keadaan sekaligus, sehingga ruang komputasinya meledak secara eksponensial. Inilah sumber kekuatannya.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Entanglement: Keterkaitan Ajaib$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 5, jsonb_build_object('text', $$Dua qubit yang terjerat (entangled) saling terhubung sedemikian rupa sehingga mengukur satu qubit langsung menentukan keadaan pasangannya, sejauh apa pun jaraknya. Einstein menyebutnya 'aksi seram dari kejauhan'. Dalam komputasi, entanglement memungkinkan qubit bekerja sebagai satu kesatuan yang terkoordinasi, bukan sebagai unit yang berdiri sendiri.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Kegunaan Nyata di Dunia Sains$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Penemuan obat: mensimulasikan interaksi molekul yang mustahil dihitung komputer biasa$$, $$Ilmu material: merancang baterai dan superkonduktor baru dari tingkat atom$$, $$Optimasi: rute logistik, portofolio keuangan, dan jadwal raksasa$$, $$Kriptografi: berpotensi memecahkan enkripsi klasik — sekaligus mendorong enkripsi tahan-kuantum$$, $$Kecerdasan buatan: mempercepat pelatihan model tertentu$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Tantangan Besar Sebelum Masuk Rumah Kita$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$Qubit sangat rapuh: gangguan sekecil apa pun (dekoherensi) menghancurkan perhitungannya, sehingga mesinnya harus didinginkan mendekati nol absolut. Jumlah qubit masih ratusan hingga ribuan, dan angka kesalahan masih tinggi — para ilmuwan mengejar 'koreksi kesalahan kuantum' agar komputer kuantum benar-benar andal. Diperkirakan butuh satu hingga dua dekade lagi sebelum manfaatnya terasa luas, tetapi fondasi revolusinya sedang dibangun hari ini.$$));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah mempelajari materi ini, kamu diharapkan mampu: (1) menjelaskan pengertian dan tujuan recount text; (2) mengidentifikasi struktur orientation, events, dan reorientation; (3) mengenali ciri kebahasaan recount text; (4) menulis recount text sederhana tentang pengalaman pribadimu.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Pengertian Recount Text$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Recount text adalah teks yang menceritakan kembali kejadian atau pengalaman yang sudah terjadi di masa lalu, secara berurutan. Tujuannya untuk memberi informasi atau menghibur pembaca. Contohnya: cerita liburan, pengalaman lomba, atau diary perjalanan. Karena menceritakan masa lalu, recount text memakai simple past tense.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Struktur Recount Text$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Orientation: pembuka yang menjawab siapa, kapan, dan di mana kejadian berlangsung$$, $$Events: rangkaian kejadian yang diceritakan secara kronologis (urutan waktu)$$, $$Reorientation: penutup berisi kesan, perasaan, atau kesimpulan penulis$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Ciri Kebahasaan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Simple past tense: went, visited, played, was/were$$, $$Time connectives: first, then, after that, finally, the next day$$, $$Action verbs: walked, swam, bought, ate$$, $$Adverb of time and place: yesterday, last week, at the beach$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Contoh Teks$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 9, jsonb_build_object('text', $$My Holiday in Yogyakarta. Last month, my family and I went to Yogyakarta by train. We arrived in the morning and went straight to Malioboro. In the afternoon, we visited Prambanan Temple and took many photos. The next day, we went to Parangtritis Beach and played sand until sunset. We were very happy. Finally, we bought bakpia as souvenirs and went home. It was an unforgettable holiday.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Latihan Soal$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Sebutkan tiga bagian struktur recount text beserta fungsinya masing-masing!$$, $$Ubah kalimat ini ke past tense: 'We go to the beach every Sunday.'$$, $$Tulis recount text 5 kalimat tentang pengalamanmu minggu lalu, lengkap dengan orientation, events, dan reorientation! Kunci: (1) orientation-events-reorientation; (2) 'We went to the beach last Sunday.'; (3) dinilai dari struktur lengkap, past tense benar, dan urutan kronologis.$$]::text[]));
INSERT INTO madevi.articles (id, business_code, taxonomy_node_id, title, slug, summary, language, reading_minutes, creator_name, creator_principal_id, access_level, is_indexed, status, attribution_type, version, is_test, created_by, updated_by)
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 0, jsonb_build_object('text', $$Tujuan Pembelajaran$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 1, jsonb_build_object('text', $$Setelah belajar materi ini, kamu bisa: (1) menjelaskan apa itu tempat umum; (2) menyebutkan macam-macam tempat umum di sekitar tempat tinggalmu; (3) menceritakan kegunaan setiap tempat umum; (4) menyebutkan aturan yang harus dipatuhi di tempat umum.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 2, jsonb_build_object('text', $$Apa Itu Tempat Umum?$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'PARAGRAPH', 3, jsonb_build_object('text', $$Tempat umum adalah tempat yang boleh dikunjungi oleh siapa saja. Berbeda dengan rumah yang bersifat pribadi, tempat umum dipakai bersama-sama oleh banyak orang. Karena dipakai bersama, kita harus menjaga kebersihan dan ketertibannya agar semua orang merasa nyaman.$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 4, jsonb_build_object('text', $$Macam-macam Tempat Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 5, jsonb_build_object('items', ARRAY[$$Pasar: tempat membeli kebutuhan sehari-hari seperti sayur dan buah$$, $$Sekolah: tempat belajar bersama guru dan teman$$, $$Masjid/musala/gereja/pura: tempat beribadah$$, $$Puskesmas/rumah sakit: tempat berobat saat sakit$$, $$Taman: tempat bermain dan bersantai$$, $$Kantor pos: tempat mengirim surat dan paket$$, $$Terminal/stasiun: tempat naik kendaraan umum$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 6, jsonb_build_object('text', $$Aturan di Tempat Umum$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 7, jsonb_build_object('items', ARRAY[$$Antre dengan tertib, jangan menyerobot$$, $$Buang sampah pada tempatnya$$, $$Tidak berteriak atau membuat gaduh$$, $$Menjaga barang milik umum, jangan merusak$$, $$Menyapa dan bersikap ramah kepada orang lain$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 8, jsonb_build_object('text', $$Latihan$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 9, jsonb_build_object('items', ARRAY[$$Apa yang dimaksud dengan tempat umum?$$, $$Sebutkan 4 tempat umum yang ada di dekat rumahmu!$$, $$Kamu ingin mengirim surat untuk nenek. Ke mana kamu harus pergi?$$]::text[]));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'HEADING', 10, jsonb_build_object('text', $$Kunci Jawaban$$));
  INSERT INTO madevi.article_blocks (id, article_id, block_type, position, content) VALUES (gen_random_uuid(), v_id, 'LIST', 11, jsonb_build_object('items', ARRAY[$$Tempat umum adalah tempat yang boleh dikunjungi oleh siapa saja dan dipakai bersama-sama$$, $$Contoh jawaban: pasar, sekolah, masjid, taman (sesuaikan dengan lingkunganmu)$$, $$Ke kantor pos$$]::text[]));
